        toBurn = _toBurn;
    }
    fallback() external payable {
        // burn gas deterministically based on toBurn (bounded by loop count)
        uint64 cnt = toBurn % 10000; // keep bounded to avoid OOG in test harness
        for (uint64 i = 0; i < cnt; i++) {
            // waste some gas
            uint256 x = i;
            x = x * 2 + 1;
        }
    }
