    function testFuzz_property(address from, uint8 n, uint256 seed) public {
        // keep domain wide but ensure non-empty _tos per precondition
        uint256 len = uint256(n) % 4 + 1; // length in 1..4

        // build _tos and v arrays
        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            // deploy adversarial callee contracts for each entry to allow malicious behavior
            // alternate between a benign EOA-like contract and a callee that returns false from fallback
            if (((seed >> (i*8)) & 0xff) % 2 == 0) {
                tos[i] = address(new BenignCallee());
            } else {
