            }
            vals[i] = uint((seed >> (i*16)) & 0xffff);
        }

        // call transfer and capture whether it completed (did not revert) and returned true
        bool ok = false;
        try c.transfer(from, address(0x1234), tos, vals) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For any admissible inputs (non-empty tos), reference C.transfer always returns true (completes successfully).
