// Adversarial helper that always returns false from its fallback when invoked via low-level call with arbitrary calldata.
contract FalseReturnCallee {
    // low-level calls to this contract will hit fallback; we explicitly return false encoded as ABI(bool)
    fallback() external payable returns (bytes memory) {
        // return abi.encode(false);
        assembly {
            // store 32 bytes (bool false = 0) at memory 0 and return 32 bytes
            mstore(0, 0)
            return(0, 0x20)
        }
    }
}

// Benign helper: does nothing and returns true from fallback
contract BenignCallee {
    fallback() external payable returns (bytes memory) {
        assembly {
            mstore(0, 1)
            mstore(0, 1) // ensure non-zero; but actual returning value isn't used by EOA callee
            return(0, 0x20)
        }
    }
}

