// Adversarial helper: deliberately consumes all gas in fallback to create a difference in low-level call behavior.
contract MaliciousCallee {
    fallback() external payable {
        // burn gas indefinitely until out (do something expensive); a simple loop using storage to avoid compiler optimization
        uint i = 0;
        while (i < 1) {
            // perform an SSTORE to keep burning gas until OOG
            assembly { sstore(0x0, 0x1) }
            i++;
        }
    }
}

