contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: a from address, an array length seed and one amount value
    // We cannot fuzz an address to create code; deploy a helper that simulates a failing callee.
    function testFuzz_property(address from, uint256 seed, uint256 v) public {
        // Keep seed small enough to bound array length but allow >0
        uint256 len = (seed % 5) + 1; // length in 1..5

        // Build _tos array of helper addresses; deploy one helper that guarantees call returns false
        FailingCallee helper = new FailingCallee();

        address[] memory tos = new address[](len);
        uint[] memory vals = new uint[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(helper);
            // vary amounts using v and index so fuzzer explores differences
            vals[i] = v + i;
        }

        // Call transfer and capture whether it returns (no revert) and the returned bool
        bool ok;
        try c.transfer(from, address(helper), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // both reference and mutant do not revert in these code paths; mark revert as failure
            ok = false;
        }

        // General rule to assert: for all admissible inputs (len>=1) the reference returns true.
        // We assert that c.transfer(...) returned true. This holds for the reference for all inputs
        // but the mutant will sometimes return false (when helper's low-level call returns false),
        // causing this assertion to fail when run against the mutant.
        assertTrue(ok);
    }
