// Adversarial helper: its fallback returns successfully but returns false to low-level calls
// by implementing no matching function and not reverting; however low-level call to a selector
// will succeed (returning true) if the callee does not revert — to emulate a failing low-level
// call (i.e., returning false), we implement a function that consumes the selector and returns
// but then self-destructs to make subsequent calls behave differently isn't appropriate.
// Instead, we provide a function that reverts for the specific selector to simulate failure.
// The mutant checks the boolean returned by call: a call that reverts yields ok=false to the caller.
contract FailingCallee {
    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    // and revert to simulate a failing low-level call.
    function transferFrom(address, address, uint256) external pure {
        revert("fail");
    }

    // Also have a fallback to satisfy any other calls (revert by default)
    fallback() external payable {
        revert("fallback");
    }
}

