pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address 'from' and an uint256 value 'val' and a boolean selector 'shouldFail'
    // We will always pass a single-element _tos array (keeps domain wide but non-empty),
    // and deploy an adversarial callee that either returns false from its fallback (simulates low-level call failure by returning false)
    // or returns true (succeeds). The reference contract always returns true; the mutant will return false when the callee indicates failure.
    function testFuzz_property(address from, uint256 val, bool shouldFail) public {
        // admissible domain: _tos must be non-empty by spec — we ensure by using length 1
        vm.assume(from != address(0x0)); // keep domain wide but avoid the zero address for clarity

        // deploy adversarial callee that can be toggled to 'fail' (i.e., return false) or 'succeed'
        AdversarialCallee adv = new AdversarialCallee();
        adv.setFail(shouldFail);

        address[] memory tos = new address[](1);
        tos[0] = address(adv);
        uint[] memory vals = new uint[](1);
        vals[0] = val;

        // call reference contract's transfer; it should always complete and return true for any non-empty tos
        bool ok;
        try c.transfer(from, address(adv), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // reference should not revert; but if it did, we treat as false
        }

        // The general fact: reference returns true for any non-empty _tos. We assert that here.
        // This is true for the given admissible inputs; the mutant would return false when shouldFail==true.
        assertTrue(ok);
    }
}

// Adversarial helper: its fallback returns (bool) via low-level call return value.
// We implement functions so that a low-level call to any selector invoked by C will hit fallback and return data
contract AdversarialCallee {
    bool public fail;
    function setFail(bool f) public {
        fail = f;
    }

    // Any call that doesn't match a function falls through to fallback.
    // We craft the fallback to return a single byte 0x00 (false) when fail==true, else 0x01 (true).
    fallback() external payable {
        if (fail) {
            assembly {
                // return 0 (false) as 32-byte false (0)
                let ptr := mload(0x40)
                mstore(ptr, 0)
                return(ptr, 0x20)
            }
        } else {
            assembly {
                let ptr := mload(0x40)
                mstore(ptr, 1)
                return(ptr, 0x20)
            }
        }
    }

    receive() external payable {
        // same behaviour for plain ether send
        if (fail) {
            assembly {
                let ptr := mload(0x40)
                mstore(ptr, 0)
                return(ptr, 0x20)
            }
        } else {
            assembly {
                let ptr := mload(0x40)
                mstore(ptr, 1)
                return(ptr, 0x20)
            }
        }
